from functools import lru_cache

def count_salary_ways(n, d):
    @lru_cache(maxsize=None)
    def dp(index):
        if index == n:
            return 1
        total_ways = 0
        for salary in range(1, d+1):
            if index == 0:
                total_ways += dp(index+1)
            else:
                total_ways += dp(index+1) * 1 ** (salary-1) * (d+1-salary) ** 1
        return total_ways

    return (dp(0) % 1000000007) % (10**9 + 7)

