import sys

def gcd(a, b):
    if a % b == 0:
        return b
    return gcd(b, a % b)

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def manhatten(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def count_disjoint_triangles(points):
    n = len(points)
    triangles = []
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                line1 = [points[i], points[j], points[k]]
                if len(line1) < 2:
                    continue
                if line1[0] > line1[1] and line1[1] > line1[2]:
                    continue
                side1 = [point - line1[0] for point in line1[1:] if line1[0] != line1[1][:]]
                if not(side1):
                    side1 = [line1[1]-line1[2]]
                side2 = [point - line1[2] for point in line1[0:1]]
                if not(side2):
                    side2 = [line1[0]-line1[1]]
                if len(side1) < 2 or len(side2) < 2:
                    continue
                gcs = gcd(len(side1), len(side2))
                sign = min([manhatten(line1[1] - line1[2], points[i]) < 0, manhatten(line1[1] - line1[2], points[j]) < 0]) > 0
                triangles.append((gcs//2, sign))
    cnt = 0
    for tri in triangles:
        for tri_2 in triangles:
            if set(tri) == set(tri_2):
                continue
            if gcd(tri[0], tri_2[0]) > 1 or tri[1] == tri_2[1]:
                continue
            gcs = gcd(2*tri[0], 2*tri_2[0])
            cnt += min([tri[0]//gcs, tri_2[0]//gcs]) if tri[1] != tri_2[1] else max([tri[0]//gcs, tri_2[0]//gcs])
