                continue
            if visited_cities[museum] and i == d - 1:
                result = max(result, max(connected_museums[next_city]))

        visited_cities[next_city] = False

    print(result)

def topological_sort_helper(museum_schedule):
    in_degree = [0] * len(museum_schedule)
    graph = [[] for _ in range(len(museum_schedule))]

    for i in range(len(museum_schedule)):
        for day in range(1, len(museum_schedule[0])):
            graph[i].append((i + len(museum_schedule[0]) * day) % len(museum_schedule))
            in_degree[(i + len(museum_schedule[0]) * day) % len(museum_schedule)] += 1

    queue = []
    for i in range(len(in_degree)):
        if in_degree[i] == 0:
            queue.append(i)
    result = []
    while queue:
        next_queue = []
        for node in queue:
            for next_node in graph[node]:
                in_degree[next_node] -= 1
                if in_degree[next_node] == 0:
                    next_queue.append(next_node)

        queue = next_queue
        result.append(queue[0])

    return result

