def is_in_triangle(triangle, point):
    return (triangle[0][0] - triangle[1][0]) * (point[1] - triangle[0][1]) - (point[0] - triangle[0][0]) * (triangle[0][1] - triangle[1][1]) < 0

def is_disjoint(triangle1, triangle2):
    return not is_in_triangle(triangle1, triangle2[0]) and not is_in_triangle(triangle1, triangle2[1]) and not is_in_triangle(triangle2, triangle1[0]) and not is_in_triangle(triangle2, triangle1[1])

def calculate_number_of_disjoint_triangles(points):
    n = len(points)
    count = 0

    for triangle1 in combinations(points, 3):
        for triangle2 in combinations(points, 3):
            if is_disjoint(triangle1, triangle2):
                count += 1

    return count

