    dp = [1] * n
    for salary, current in enumerate(predecessors):
        for next_sal in predecessors[current]:
            dp[salary] = (dp[salary] - dp[next_sal] + d) % (10**9 + 7)
            if next_sal == current: 
                dp[salary] += 1
            if next_sal != current:
                dp[salary] %= (10**9 + 7)
    return dp[0]


