from collections import defaultdict

def rebuild_sequence(s, p):
    sequence = []
    for i, ch in enumerate(s):
        found = False
        for j in range(len(p)):
            if ch == p[j]:
                sequence.append(j)
                found = True
                break
        if not found:
            return -1
    return len(sequence)

def update_sequence(sequence, operations):
    for operation in operations:
        if operation == 1:
            for j in range(operation[1], operation[2] + 1):
                sequence[j-1] = operation[0]
        else:
            p = operation
            d = 2 * (rebuild_sequence(p, list(p)) - len(p) + 1)
            total = 0
            for i in sequence:
                total += d if i <= d else d - (total + d // len(list(set(p[i:]))) - total) % d

def solve(n, m, k, s, operations):
    sequences = defaultdict(list)

    for op in operations:
        if op == 1:
            sequences[op[0]].append((op[1], op[2], op[3]))
        else:
            sequences[op[1] - 1].append(op[2] - 1)

    for j in range(len(s)):
        for operation in sequences[j]:
            if operation == 1:
                positions = sequences[operation[0]][:]
                positions[j] = operation[1]
                sequences[operation[0]] = positions
            else:
                p, k = sequences[j]
                if rebuild_sequence(s, list(p)) < k:
                    break
                sequences[k - 1] = sequences[j]
                sequences[j] = []

    for i in range(len(s) - 1, -1, -1):
        if len(sequences[i]) > 0 and rebuild_sequence(s, list(sequences[i][0])) >= i:
            res = update_sequence([ sequences[i][0] ], operations[ : i + 1 ])
            for l, r, ch in operations[i + 1:]:
                res += rebuild_sequence(s[r: l], list(ch)) - lParam
                res %= k ** (r - l)

            return res

