    for i in range(n):
        throughs = process_router(lines[i][-1], lines[i][1])
        if throughs == -1:
            return -1
        graphs[throughs[0]].add(i + 1)

    result = []
    for i in range(1, n):
        current = []
        for router in range(1, i + 1):
            neighbors = graphs[router]
            if len(neighbors) > 1:
                result.append((router, neighbors.pop()))
                current.append(router + 1)
        if len(result) <= n - 3:
            while current:
                router = current.pop()
                router_neighbors = graphs[router]
                if router_neighbors == (1 for _ in range(len(graphs[router]))):
                    routers = graphs.pop(router)
                    current.sort()
                    if len(current) == 1:
                        current.reverse()
                        result.append((-1,))
                    else:
                        result.append(tuple(current))
                    break
                if not router_neighbors.issuperset(routers):
                    result.append(tuple(current))
                    break
                neighbor = router_neighbors.difference(routers)[0]
                result.append((router, neighbor))
                routers.discard(neighbor)
                current.append(neighbor)

    return len(result) == n - 1

