import networkx as nx

def tof(graph):
    n = len(graph.nodes)
    visited = [False] * n

    def dfs(v):
        nonlocal neighbour_index
        visited[v] = True
        neighbour_index += 1
        count[v] += 1
        for u in list(graph.predecessors(v)):
            if not visited[u]:
                dfs(u)
                break  # Only one call needed for an edge between two vertices
            else:
                for i, l in enumerate(sorted(graph.neighbors(u))):
                    if l == v:
                        unblogged.add(i)
                        break
                else:
                    neighbour_index += 1  # Break not needed; unblogged contains all vertices
                    for i in range(len(unblogged)):
                        dfs(unblogged[i])

    for u in range(n):
        nb_history = set()
        unblogged = set(list(graph.predecessors(u)))
        neighbour_index = 0
        count = [-1] * n
        dfs(u)
    return neighbour_index
