import math

def can_reach_highest(a, n, p, h):
    h_mod_i = [j for j in range(a, n * p, a) if j - h >= 0]
    while a <= h_mod_i[-1] + h:
        if h_mod_i == [i for i in range(a, n * p, a) if i - h >= 0]:
            return "YES"
        h %= (i + 1)
        while a <= h_mod_i[-1] + h:
            if h_mod_i == [i for i in range(a, n * p, a) if i - h >= 0]:
                return "YES"
            h %= (i + 1)
    return "NO"

