def isPrime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def gcd(a, b):
    """Calculate the greatest common divisor of two numbers."""
    while b:
        a, b = b, a % b
    return a

def find_highest_tax(a, n, p, h, remainder):
    """Find the maximum height a Doodler can reach within the bounds of the platforms."""
    if gcd(a, p) == 1:
        if remainder - h <= p:
            return 'YES'
    return 'NO'

