import sys

def max_museums(days, cities, roads, museum_schedules):
    graph = {i: {} for i in range(1, cities + 1)}
    for u, v in roads:
        graph[u][v] = 1
    for i in graph:
        graph[i] = sorted(graph[i].items())
        del graph[i][::-1]
    dp = [[[[0 for k in range(days)] for k in range(days)] for k in graph]]

    def get_next_day(schedule):
        for i in range(len(schedule) - 1, -1, -1):
            if schedule[i] == '1':
                return i
        return -1

    for day in range(days):
        next_days = sys.maxsize
        for city in range(1, cities + 1):
            schedule = museum_schedules[city - 1][day]
            day_roads = set()
            for road in graph[city]:
                if schedule[road] == '1':
                    day_roads.add(graph[road])
            if len(day_roads) != 0:
                for next_city in day_roads:
                    dp[city][next_city][day + 1] = max(dp[city][next_city][day + 1],
                                                       dp[city][city][day] + 1)
                    next_days = min(next_days, dp[city][next_city][day + 1])
        dp[city][city][day + 1] = next_days
    return dp[-1][-1][-1]

# Example usage
