from collections import defaultdict, deque

def partial_sum(n, *args):
    primes = [2, 3, 5, 7, 11, 13]
    result = 1
    for i in range(len(args)):
        if primes[i] > n:
            break
        for j in range(i + 1, len(args)):
            while primes[j] <= n:
                result *= args[j] / primes[i]
    return int(result % (10**9 + 7))

def solve(*uf_scores):
    uf_scores_sum = sum(uf_scores)
    maximum_score = partial_sum(uf_scores_sum, uf_scores_sum // 4, uf_scores_sum // 8)
    final_score = uf_scores_sum - maximum_score
    if final_score in [sum(uf_scores) // 500 * 1500, sum(uf_scores) // 1000 * 2000, sum(uf_scores) // 800 * 2500]:
        return str(maximum_score + 1)
    if maximum_score in [sum(uf_scores) // 1000 * 2000, sum(uf_scores) // 5000 * 2500]:
        return str(maximum_score + 2)
    if len(uf_scores) % 2:
        return '2'
    return '1'
