from itertools import combinations

def are_disjoint(triangle1, triangle2):
    for i in range(3):
        for j in range(i+1, 3):
            if (triangle1[i] + triangle2[i] + triangle1[j] + triangle2[j]) == 0:
                return False
            if (triangle1[i] + triangle2[j] + triangle1[j] + triangle2[i]) == 0:
                return False
    return True

def count_disjoint_triangles(points):
    total_triangles = combinations(points, 3)
    disjoint_triangles = 0
    for triangle in total_triangles:
        group1 = {tuple(point) for point in triangle}
        for other_triangle in total_triangles:
            if are_disjoint(triangle, tuple(other_triangle) - group1) and are_disjoint(other_triangle, triangle - group1):
                if not are_disjoint(triangle, other_triangle):
                    disjoint_triangles += 1
    return disjoint_triangles

n = int(input())
points = [tuple(map(int, input().split())) for _ in range(n)]

print(count_disjoint_triangles(points))
